import{_ as o,c as i,o as t,ag as a}from"./chunks/framework.BlG8Ex8O.js";const p=JSON.parse('{"title":"Project Name: Nikola G. Portfolio","description":"","frontmatter":{},"headers":[],"relativePath":"CLAUDE.md","filePath":"CLAUDE.md"}'),c={name:"CLAUDE.md"};function d(s,e,n,l,r,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="project-name-nikola-g-portfolio" tabindex="-1">Project Name: Nikola G. Portfolio <a class="header-anchor" href="#project-name-nikola-g-portfolio" aria-label="Permalink to &quot;Project Name: Nikola G. Portfolio&quot;">​</a></h1><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><ul><li>Framework: VitePress 1.x (static site generator on top of Vite + Vue 3)</li><li>Styling: TailwindCSS 3 with custom color tokens (<code>clrPrimary</code>, <code>clrSecondary</code>, <code>clrAccent</code>, <code>clrAccentLight</code>)</li><li>Language: JavaScript (Vue SFCs + <code>.js</code> config files; <code>config.ts</code> is the one TS file)</li><li>Animations: AOS (Animate on Scroll) — initialized and refreshed in <code>.vitepress/theme/index.js</code></li><li>Icons/UI: Heroicons (<code>@heroicons/vue</code>) and Headless UI (<code>@headlessui/vue</code>)</li><li>CRITICAL: Do NOT introduce external component libraries (e.g. Vuetify, PrimeVue). Write native Tailwind for all styling.</li></ul><h2 id="architecture-guidelines" tabindex="-1">Architecture Guidelines <a class="header-anchor" href="#architecture-guidelines" aria-label="Permalink to &quot;Architecture Guidelines&quot;">​</a></h2><ul><li>VitePress config lives in <code>.vitepress/config.ts</code></li><li>Custom theme entry point is <code>.vitepress/theme/index.js</code> — this is where <code>CustomLayout</code> wraps every page with <code>AppNavbar</code> + <code>DefaultTheme.Layout</code> + <code>AppFooter</code></li><li>All Vue components live in <code>.vitepress/theme/components/</code></li><li>Global styles go in <code>.vitepress/theme/custom.css</code>; base/reset styles in <code>.vitepress/theme/assets/</code></li><li>Homepage content is composed in <code>/index.md</code> using <code>layout: page</code> and inline component imports</li><li>Blog posts live in <code>/posts/*.md</code>; the posts index page is <code>/posts/index.md</code></li><li>Static assets (images, icons, PDFs) go in <code>/public/</code></li><li>Keep components modular. Never create files larger than 300 lines of code.</li></ul><h2 id="coding-conventions" tabindex="-1">Coding Conventions <a class="header-anchor" href="#coding-conventions" aria-label="Permalink to &quot;Coding Conventions&quot;">​</a></h2><ul><li>Use Vue 3 Composition API (<code>&lt;script setup&gt;</code> syntax preferred)</li><li>Use <code>async/await</code> instead of <code>.then()</code> promise chains</li><li>Component filenames use PascalCase and the <code>App</code> prefix for top-level sections (e.g. <code>AppHeader.vue</code>, <code>AppProjects.vue</code>)</li><li>CSS variables/Tailwind color tokens are defined in <code>tailwind.config.js</code> — use those tokens instead of raw hex/rgb values</li><li>AOS data attributes (<code>data-aos</code>, <code>data-aos-delay</code>) are the preferred way to add scroll animations</li></ul><h2 id="commands-for-claude" tabindex="-1">Commands for Claude <a class="header-anchor" href="#commands-for-claude" aria-label="Permalink to &quot;Commands for Claude&quot;">​</a></h2><ul><li>Dev server: <code>npm run dev</code></li><li>Build command: <code>npm run build</code></li><li>Preview build: <code>npm run preview</code></li><li>Linting command: <code>npm run lint</code></li><li>No test framework is configured — do not assume <code>npm run test</code> exists</li></ul>',9)])])}const h=o(c,[["render",d]]);export{p as __pageData,h as default};
